insert into public.curriculum_outcomes (outcome_id,source_id,subject_id,standard_id,grade,unit_id,code,outcome_text,source_page,source_pdf_page) values
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-01', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 1', 'อธิบาย และสรุปสมบัติที่สำคัญของสิ่งมีชีวิตและความสัมพันธ์ของการจัดระบบในสิ่งมีชีวิตที่ทำให้สิ่งมีชีวิตดำรงชีวิตอยู่ได้', 135, 142),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-02', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 2', 'อภิปราย และบอกความสำคัญของการระบุปัญหา ความสัมพันธ์ระหว่างปัญหา สมมติฐานและวิธีการตรวจสอบสมมติฐาน รวมทั้งออกแบบการทดลองเพื่อตรวจสอบสมมติฐาน', 135, 142),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-03', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 3', 'สืบค้นข้อมูล อธิบายเกี่ยวกับสมบัติของน้ำและบอกความสำคัญของน้ำที่มีต่อสิ่งมีชีวิตและยกตัวอย่างธาตุชนิดต่าง ๆ ที่มีความสำคัญต่อร่างกายสิ่งมีชีวิต', 135, 142),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-04', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 4', 'สืบค้นข้อมูล อธิบายโครงสร้างของคาร์โบไฮเดรตระบุกลุ่มของคาร์โบไฮเดรต รวมทั้งความสำคัญของคาร์โบไฮเดรตที่มีต่อสิ่งมีชีวิต', 136, 143),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-05', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 5', 'สืบค้นข้อมูล อธิบายโครงสร้างของโปรตีนและความสำคัญของโปรตีนที่มีต่อสิ่งมีชีวิต', 136, 143),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-06', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 6', 'สืบค้นข้อมูล อธิบายโครงสร้างของลิพิดและความสำคัญของลิพิดที่มีต่อสิ่งมีชีวิต', 136, 143),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-07', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 7', 'อธิบายโครงสร้างของกรดนิวคลิอิก และระบุชนิดของกรดนิวคลิอิก และความสำคัญของกรดนิวคลิอิกที่มีต่อสิ่งมีชีวิต', 136, 143),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-08', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 8', 'สืบค้นข้อมูล และอธิบายปฏิกิริยาเคมีที่เกิดขึ้นในสิ่งมีชีวิต', 136, 143),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-09', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 9', 'อธิบายการทำงานของเอนไซม์ในการเร่งปฏิกิริยาเคมีในสิ่งมีชีวิต และระบุปัจจัยที่มีผลต่อการทำงานของเอนไซม์', 136, 143),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-10', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 10', 'บอกวิธีการ และเตรียมตัวอย่างสิ่งมีชีวิตเพื่อศึกษาภายใต้กล้องจุลทรรศน์ใช้แสงวัดขนาดโดยประมาณ และวาดภาพที่ปรากฏภายใต้กล้อง บอกวิธีการใช้ และการดูแลรักษากล้องจุลทรรศน์ใช้แสงที่ถูกต้อง', 137, 144),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-11', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 11', 'อธิบายโครงสร้างและหน้าที่ของส่วนที่ห่อหุ้มเซลล์ของเซลล์พืชและเซลล์สัตว์', 137, 144),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-12', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 12', 'สืบค้นข้อมูล อธิบาย และระบุชนิดและหน้าที่ของออร์แกเนลล์', 137, 144),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-13', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 13', 'อธิบายโครงสร้างและหน้าที่ของนิวเคลียส', 137, 144),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-14', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 14', 'อธิบาย และเปรียบเทียบการแพร่ ออสโมซิสการแพร่แบบฟาซิลิเทต และแอกทีฟทรานสปอร์ต', 138, 145),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-15', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 15', 'สืบค้นข้อมูล อธิบาย และเขียนแผนภาพการลำเลียงสารโมเลกุลใหญ่ออกจากเซลล์ด้วยกระบวนการเอกโซไซโทซิสและการลำเลียงสารโมเลกุลใหญ่เข้าสู่เซลล์ด้วยกระบวนการเอนโดไซโทซิส', 138, 145),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-16', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 16', 'สังเกตการแบ่งนิวเคลียสแบบไมโทซิสและแบบไมโอซิสจากตัวอย่างภายใต้กล้องจุลทรรศน์พร้อมทั้งอธิบายและเปรียบเทียบการแบ่งนิวเคลียสแบบไมโทซิส และแบบไมโอซิส', 138, 145),
('ipst-sci2560-add-biology-strand-1-ม.4-outcome-17', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-1', 'M4', 'biology-strand-1-M4', 'สาระชีววิทยา 1 ม.4 ข้อ 17', 'อธิบาย เปรียบเทียบ และสรุปขั้นตอนการหายใจระดับเซลล์ในภาวะที่มีออกซิเจนเพียงพอ และภาวะที่มีออกซิเจนไม่เพียงพอ', 139, 146),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-01', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 1', 'สืบค้นข้อมูล อธิบาย และสรุปผลการทดลองของเมนเดล', 140, 147),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-02', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 2', 'อธิบาย และสรุปกฎแห่งการแยก และกฎแห่งการรวมกลุ่มอย่างอิสระ และนำกฎของเมนเดลนี้ ไปอธิบายการถ่ายทอดลักษณะทางพันธุกรรมและใช้ในการคำนวณโอกาสในการเกิดฟีโนไทป์และจีโนไทป์แบบต่าง ๆ ของรุ่นF 1 และ F 2', 140, 147),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-03', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 3', 'สืบค้นข้อมูล วิเคราะห์ อธิบาย และสรุปเกี่ยวกับการถ่ายทอดลักษณะทางพันธุกรรม ที่เป็นส่วนขยายของพันธุศาสตร์เมนเดล', 140, 147),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-04', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 4', 'สืบค้นข้อมูล วิเคราะห์ และเปรียบเทียบลักษณะทางพันธุกรรมที่มีการแปรผันไม่ต่อเนื่องและลักษณะทางพันธุกรรมที่มีการแปรผันต่อเนื่อง', 140, 147),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-05', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 5', 'อธิบายการถ่ายทอดยีนบนโครโมโซม และยกตัวอย่างลักษณะทางพันธุกรรมที่ถูกควบคุมด้วยยีนบนออโตโซมและยีนบนโครโมโซมเพศ', 141, 148),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-06', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 6', 'สืบค้นข้อมูล อธิบายสมบัติและหน้าที่ของสารพันธุกรรม โครงสร้างและองค์ประกอบทางเคมีของ DNA และสรุปการจำลอง DNA', 141, 148),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-07', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 7', 'อธิบาย และระบุขั้นตอนในกระบวนการสังเคราะห์โปรตีนและหน้าที่ของ DNA และRNA แต่ละชนิดในกระบวนการสังเคราะห์โปรตีน', 141, 148),
('ipst-sci2560-add-biology-strand-2-ม.4-outcome-08', 'TH-SCI-ADDITIONAL-2560', 'biology', 'biology-strand-2', 'M4', 'biology-strand-2-M4', 'สาระชีววิทยา 2 ม.4 ข้อ 8', 'สรุปความสัมพันธ์ระหว่างสารพันธุกรรม แอลลีลโปรตีน ลักษณะทางพันธุกรรม และเชื่อมโยงกับความรู้เรื่องพันธุศาสตร์เมนเดล', 141, 148),
